<template>
	<view class="view-content">
		<view class="view-content-body">
			<view>
				<view class="input-row border input-height">
					<view class="title">
						<view class="title-icon" style="">
							<image style="width: 32px;height: 32px;" src="../../static/img/reg_phone.jpg"></image>
						</view>
					</view>
					<m-input type="text" focus clearable v-model="account" placeholder="请输入手机号"></m-input>
				</view>
				<view class="input-row border input-height">
					<view class="title">
						<view class="title-icon" style="">
							<image style="width: 32px;height: 32px;" src="../../static/img/reg_pwd.jpg"></image>
						</view>
					</view>
					<m-input type="password" displayable v-model="password" placeholder="请输入密码"></m-input>
				</view>
				<view class="input-row border input-height">
					<view class="title">
						<view class="title-icon" style="">
							<image style="width: 32px;height: 32px;" src="../../static/img/reg_invet.jpg"></image>
						</view>
					</view>
					<m-input type="text" clearable v-model="invitePhone" placeholder="请输入邀请人电话"></m-input>
				</view>
			</view>
			<view class="btn-row">
				<button type="primary" hover-class="none" class="primary" @tap="register">注册</button>
			</view>
			<view class="download">

				<view v-if="isweiixn">
					<a href="#" download="sqb.apk" @click="ckdownload">已有账号点此直接下载APP</a>
				</view>
				<view v-else-if="isIos()">
					<a href="https://f.hlgbg.cn/app.php/MTc4Mg==" >已有账号点此直接下载APP</a>
				</view>
				<view v-else>
					<a href="http://139.155.8.217:8081/sqb.apk" download="sqb.apk" @click="ckdownload">已有账号点此直接下载APP</a>
				</view>
			</view>
			<view class = "weixin-tip" v-if="isWeiXin()">
				<p><img src="../../static/img/live_weixin.png" style="max-width: 100%; height: auto;" alt="微信打开" /></p>
			</view>
		</view>
		
	</view>
</template>

<script>
	import mInput from "../../components/m-input.vue";
	export default {
		components: {
			mInput
		},
		data() {
			return {
				account: "",
				password: "",
				inviteid: 0,
				invitePhone: "",
				isweiixn:false
			};
		},
		methods: {
			register() {
				if (this.account.length < 5) {
					uni.showToast({
						icon: "none",
						title: "账号最短为 5 个字符"
					});
					return;
				}
				if (this.password.length < 6) {
					uni.showToast({
						icon: "none",
						title: "密码最短为 6 个字符"
					});
					return;
				}
				if (this.invitePhone.length < 11 || this.inviteid == 0) {
					uni.showToast({
						icon: "none",
						title: "邀请人不合法"
					});
					return;
				}

				const data = {
					account: this.account,
					password: this.password,
					inviteid: this.inviteid
				};

				uni.request({
					url: `${this.baseUrl}/api/Member/PostRegisterUser`,
					data: {
						phone: this.account,
						password: this.password,
						inviteid: this.inviteid
					},
					method: "POST",
					header: {
						"Content-Type": "application/json"
					},
					success: res => {
						if (res.data.statusCode == 200) {
							uni.showModal({
								title: "提示",
								content: "您已注册成功, 请下载APP后登录!",
								success: function(res) {
									if (res.confirm) {
										//跳转到送钱宝app下载页面
										uni.navigateTo({ url: "../reg/downloadapp" });
										/*uni.navigateTo({
											url: "../login/login"
										}); //TODO 导航下载APP*/
									} else if (res.cancel) {
										console.log("用户点击取消");
									}
								}
							});
						} else {
							uni.showToast({
								icon: "none",
								title: res.data.msg
							});
						}
					},
					fail: () => {
						uni.showToast({
							icon: "none",
							title: "网络异常"
						});
					}
				});
			},
			isWeiXin: function() {
				var ua = window.navigator.userAgent.toLowerCase();
				if (ua.match(/MicroMessenger/i) == "micromessenger") {
					return true; // 是微信端
				} else {
					return false;
				}
			},
			isIos(){
				var u = window.navigator.userAgent;
				var  ios  =  !!u.match(/\(i[^;]+;( U;)? CPU.+Mac OS X/);        
				var  iPad  =  u.indexOf('iPad')  >  -1;        
				var  iPhone  =  u.indexOf('iPhone')  >  -1  ||  u.indexOf('Mac')  >  -1;        
				if  (ios  ||  iPad  ||  iPhone)  {            
					return  true;        
				} 
				else  {            
					return  false;        
				}
			},
			ckdownload: function() {
				if (this.isWeiXin()) {
					uni.showModal({
						title: "提示",
						content: "请点击右上角,在浏览器中打开,并安装应用!",
						success: function(res) {
							if (res.confirm) {} else if (res.cancel) {}
						}
					});
				} else {
					uni.showToast({
						icon: "none",
						title: "后台下载中,请稍后...!"
					});
				}
			}
		},
		onLoad: function(option) {
			if (option.inviteid == undefined || option.inviteid == "") {
				uni.showToast({
					icon: "none",
					title: "邀请链接异常!无法注册,请联系开发人员!"
				});
			}
			this.inviteid = option.inviteid;
			uni.request({
				url: `${this.baseUrl}/api/Member/GetInviteUserPhone?id=${option.inviteid}`,
				method: "GET",
				header: {
					"Content-Type": "application/json"
				},
				success: res => {
					if (res.data.statusCode == 200) {
						this.invitePhone = res.data.result;
					} else {
						uni.showToast({
							icon: "none",
							title: res.data.msg
						});
					}
				},
				fail: () => {
					uni.showToast({
						icon: "none",
						title: "网络异常"
					});
				}
			});
			if (this.isWeiXin()) {
				this.isweiixn = true;
			}
		}
	};
</script>

